32	/**
33	 * Simple JavaBean domain object representing an owner.
34	 *
35	 * @author Ken Krebs
36	 * @author Juergen Hoeller
37	 * @author Sam Brannen
38	 * @author Michael Isvy
39	 */
40	@Entity
41	@Table(name = "owners")
42	public class Owner extends Person {
43	    @Column(name = "address")
44	    @NotEmpty
45	    private String address;
46	
47	    @Column(name = "address_line1")
48	    private String addressLine1;
49	
50	    @Column(name = "address_line2")
51	    private String addressLine2;
52	
53	    @Column(name = "city")
54	    @NotEmpty
55	    private String city;
56	
57	    @Column(name = "telephone")
58	    @NotEmpty
59	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
60	    private String telephone;
61	
62	    @Column(name = "email")
63	    private String email;
64	
65	    @Column(name = "registration_date", columnDefinition = "DATE")
66	    private LocalDate registrationDate;
67	
68	    @Column(name = "birth_date", columnDefinition = "DATE")
69	    private LocalDate birthDate;
70	
71	    @Column(name = "customer_code")
72	    private String customerCode;
73	
74	    @Column(name = "household_id")
75	    private String householdId;
76	
77	    @Column(name = "namesake_count")
78	    private Integer namesakeCount;
79	
80	    @Column(name = "household_size")
81	    private Integer householdSize;
82	
83	    @Column(name = "postcode")
84	    private String postcode;
85	
86	    @Column(name = "bulk_signup_warning")
87	    private Boolean bulkSignupWarning;
88	
89	    @Column(name = "possible_duplicate")
90	    private Boolean possibleDuplicate;
91	
92	    @Column(name = "possible_duplicate_of")
