100	     * is absent or in no known range. Any city not listed derives the locality {@code 'UNKNOWN'}.
101	     */
102	    private static final Map<String, String> CITY_REGION = Map.of(
103	        "Sydney", "NSW",
104	        "Melbourne", "VIC",
105	        "Brisbane", "QLD");
