107	    /**
108	     * Inclusive 4-digit postcode range per region, used to derive {@link #getLocality() locality}
109	     * from the postcode in preference to the city: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
110	     */
111	    private static final Map<String, int[]> REGION_POSTCODE = Map.of(
112	        "NSW", new int[] {2000, 2099},
113	        "VIC", new int[] {3000, 3099},
114	        "QLD", new int[] {4000, 4099});
