118	     * {@link #getLocality() locality}: NSW->Australia/Sydney, VIC->Australia/Melbourne,
119	     * QLD->Australia/Brisbane. A locality not listed derives a {@code null} timezone.
120	     */
121	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
122	        "NSW", "Australia/Sydney",
123	        "VIC", "Australia/Melbourne",
124	        "QLD", "Australia/Brisbane");
