166	    /**
167	     * Known E.164 country codes whose national-number length is fixed, used to split the stored
168	     * telephone into its country code and national digits for display: Australia ({@code '61'}) and
169	     * the North American Numbering Plan ({@code '1'}). A number whose country code is not listed is
170	     * split by taking its leading digit as the (minimal) country code.
171	     */
172	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
173	
174	    /**
175	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans: the country code, a
176	     * single space, then the national digits grouped in threes from the left (e.g. the stored
177	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw telephone itself stays in
178	     * E.164 form. Returns the stored value unchanged when it is absent or not a {@code '+'}-prefixed
179	     * digit string.
180	     *
181	     * @return the human-readable telephone, or the stored value when it cannot be formatted
182	     */
183	    public String getTelephoneDisplay() {
184	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
185	            return this.telephone;
186	        }
187	        String digits = this.telephone.substring(1);
188	        String countryCode = extractCountryCode(digits);
189	        String national = digits.substring(countryCode.length());
190	        StringBuilder display = new StringBuilder("+").append(countryCode);
191	        for (int i = 0; i < national.length(); i += 3) {
192	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
193	        }
194	        return display.toString();
195	    }
196	
197	    /**
198	     * Splits the country code off an E.164 digit string (country code followed by national digits,
199	     * without the leading {@code '+'}). A country code listed in {@link #COUNTRY_NATIONAL_LENGTH}
200	     * whose required national-number length matches the remaining digits is preferred; failing that,
201	     * the leading digit is used as the country code.
202	     *
203	     * @param digits the E.164 digits without the leading {@code '+'}
204	     * @return the country-code portion of {@code digits}
205	     */
206	    private static String extractCountryCode(String digits) {
207	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
208	            String code = entry.getKey();
209	            if (digits.startsWith(code) && digits.length() - code.length() == entry.getValue()) {
210	                return code;
211	            }
212	        }
213	        return digits.substring(0, 1);
214	    }
