272	    /**
273	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
274	     * the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived
275	     * from the owner's own customer code and registration date; {@code null} when either is absent.
276	     *
277	     * @return the membership number, or {@code null} when it cannot be derived
278	     */
279	    public String getMembershipNumber() {
280	        if (this.customerCode == null || this.registrationDate == null) {
281	            return null;
282	        }
283	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
284	    }
285	
286	    /**
287	     * The owner's Luhn check digit, a single digit (0-9) computed over the digits contained in the
288	     * {@link #getCustomerCode() customer code}. Non-digit characters (such as the separators and the
289	     * letter prefixes) are ignored. Returns {@code null} when the customer code is absent.
290	     *
291	     * @return the Luhn check digit, or {@code null} when the customer code is absent
292	     */
293	    public Integer getCheckDigit() {
294	        if (this.customerCode == null) {
295	            return null;
296	        }
297	        int sum = 0;
298	        boolean dbl = true;
299	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
300	            char c = this.customerCode.charAt(i);
301	            if (c < '0' || c > '9') {
302	                continue;
303	            }
304	            int d = c - '0';
305	            if (dbl) {
306	                d *= 2;
307	                if (d > 9) {
308	                    d -= 9;
309	                }
310	            }
311	            sum += d;
312	            dbl = !dbl;
313	        }
314	        return (10 - (sum % 10)) % 10;
315	    }
316	
317	    /**
318	     * The owner's membership points, the score the {@link #getMembershipLevel() membership level} is
319	     * derived from. The score starts at 0 and gains: 2 when an email address is present, 1 when the
320	     * owner has no namesakes ({@code namesakeCount} is 0), 2 for a household of 3 or more members
321	     * ({@code householdSize} is at least 3), and 3 when the owner's tenure exceeds 365 days (see
322	     * {@link #getTenureDays()}). Because a newly created owner has zero tenure, the tenure points are
323	     * never awarded at create time.
324	     *
325	     * @return the membership points, a non-negative integer
326	     */
327	    public Integer getMembershipPoints() {
328	        int points = 0;
329	        boolean hasEmail = this.email != null && !this.email.isBlank();
330	        if (hasEmail) {
331	            points += 2;
332	        }
333	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
334	        if (hasNoNamesakes) {
335	            points += 1;
336	        }
337	        if (this.householdSize != null && this.householdSize >= 3) {
338	            points += 2;
339	        }
340	        Long tenureDays = getTenureDays();
341	        if (tenureDays != null && tenureDays > 365) {
342	            points += 3;
343	        }
344	        return points;
345	    }
346	
347	    /**
348	     * The owner's numeric membership level, mapped from the {@link #getMembershipPoints() membership
349	     * points}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4
350	     * for 6 or more points.
351	     *
352	     * @return the membership level, an integer from 1 to 4
353	     */
354	    public Integer getMembershipLevel() {
355	        int points = getMembershipPoints();
356	        if (points <= 1) {
357	            return 1;
358	        }
359	        if (points <= 3) {
360	            return 2;
361	        }
362	        if (points <= 5) {
363	            return 3;
364	        }
365	        return 4;
366	    }
367	
368	    /**
369	     * The owner's tenure in whole days, the number of days elapsed from the
370	     * {@link #getRegistrationDate() registration date} to the server's current date. A tenure of more
371	     * than 365 days is what raises the {@link #getMembershipLevel() membership level} to 4. Returns
372	     * {@code null} when no registration date has been set yet.
373	     *
374	     * @return the tenure in whole days, or {@code null} when the registration date is absent
375	     */
376	    public Long getTenureDays() {
377	        if (this.registrationDate == null) {
378	            return null;
379	        }
380	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
381	    }
382	
383	    /**
384	     * The owner's locality, the canonical region string. Once the owner has a
385	     * {@link #getCustomerCode() customer code} the locality is the {@code <REGION>} component of that
386	     * code (the text before the first {@code '-'}), so the locality and the identity share a single
387	     * source of truth. Before the customer code is assigned (for example while a create is still
388	     * validating the postcode) it falls back to the region the code will be built from: the
389	     * {@link #getPostcode() postcode} looked up by range first (NSW 2000-2099, VIC 3000-3099,
390	     * QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
391	     * Brisbane->QLD), and finally {@code 'UNKNOWN'} when neither resolves to a region.
392	     *
393	     * @return the canonical region string, or {@code 'UNKNOWN'}
394	     */
395	    public String getLocality() {
396	        if (this.customerCode != null) {
397	            int dash = this.customerCode.indexOf('-');
398	            return dash >= 0 ? this.customerCode.substring(0, dash) : this.customerCode;
399	        }
400	        return deriveRegion();
401	    }
402	
403	    /**
404	     * The owner's IANA timezone name, derived from the owner's {@link #getLocality() locality} via the
405	     * fixed region-to-timezone table: NSW->Australia/Sydney, VIC->Australia/Melbourne,
406	     * QLD->Australia/Brisbane. Returns {@code null} when the locality is not one of these regions (for
407	     * example the {@code 'UNKNOWN'} locality of a city with no known region).
408	     *
409	     * @return the IANA timezone name, or {@code null} when the locality has no mapped timezone
410	     */
411	    public String getTimezone() {
412	        return REGION_TIMEZONE.get(getLocality());
413	    }
414	
415	    /**
416	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
417	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
418	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
419	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
420	     * the same region for known cities but disambiguates cities that share a name.
421	     *
422	     * @return the canonical region string, or {@code 'UNKNOWN'}
423	     */
424	    private String deriveRegion() {
425	        String region = regionFromPostcode();
426	        if (region != null) {
427	            return region;
428	        }
429	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
430	    }
431	
432	    /**
433	     * Builds this owner's customer code, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is the
434	     * region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
435	     * {@link #deriveRegion()}) and {@code HASH8} is the first 8 upper-case hexadecimal characters of
436	     * the SHA-256 digest of the owner's normalized telephone concatenated with its last name (e.g.
437	     * {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a pure function of the
438	     * owner's region, telephone and last name. Call this once at create time and store the result via
439	     * {@link #setCustomerCode(String)}, which thereafter backs {@link #getLocality()},
440	     * {@link #getMembershipNumber()} and {@link #getCheckDigit()}.
441	     *
442	     * @return the assembled customer code
443	     */
444	    public String buildCustomerCode() {
445	        return deriveRegion() + "-" + sha256Hex8(this.telephone + this.getLastName());
446	    }
447	
448	    /**
449	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
450	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
451	     *
452	     * @param value the value to hash
453	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
454	     */
455	    private static String sha256Hex8(String value) {
456	        try {
457	            byte[] digest = MessageDigest.getInstance("SHA-256")
458	                .digest(value.getBytes(StandardCharsets.UTF_8));
459	            StringBuilder hex = new StringBuilder(8);
460	            for (int i = 0; i < 4; i++) {
461	                hex.append(String.format("%02X", digest[i]));
462	            }
463	            return hex.toString();
464	        }
465	        catch (NoSuchAlgorithmException e) {
466	            throw new IllegalStateException("SHA-256 algorithm not available", e);
467	        }
468	    }
469	
470	    /**
471	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
472	     * absent, not a 4-digit number, or in no known range.
473	     *
474	     * @return the matching region, or {@code null}
475	     */
476	    private String regionFromPostcode() {
477	        if (this.postcode == null) {
478	            return null;
479	        }
480	        int value;
481	        try {
482	            value = Integer.parseInt(this.postcode.trim());
483	        }
484	        catch (NumberFormatException ex) {
485	            return null;
486	        }
487	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
488	            int[] range = entry.getValue();
489	            if (value >= range[0] && value <= range[1]) {
490	                return entry.getKey();
491	            }
492	        }
493	        return null;
494	    }
495	
496	    /**
497	     * The owner's preferred contact channel, derived from the owner's details. Returns
498	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
499	     *
500	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
501	     */
502	    public String getContactPreference() {
503	        boolean hasEmail = this.email != null && !this.email.isBlank();
504	        return hasEmail ? "EMAIL" : "PHONE";
505	    }
506	
507	    /**
508	     * The owner's identity key, the single derived value used for duplicate detection. It is the
509	     * owner's normalized telephone, email (empty when absent) and household id joined with
510	     * {@code '|'} ({@code '<telephone>|<email>|<householdId>'}); any absent ({@code null}) component
511	     * contributes an empty string. Two owners are duplicates exactly when their whole identity keys
512	     * are equal, so two members of the same household with different telephones differ here and are
513	     * both allowed.
514	     *
515	     * @return the derived identity key
516	     */
517	    public String getIdentityKey() {
518	        return (this.telephone == null ? "" : this.telephone) + "|"
519	            + (this.email == null ? "" : this.email) + "|"
520	            + (this.householdId == null ? "" : this.householdId);
521	    }
