579	    /**
580	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
581	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
582	     */
583	    @PrePersist
584	    void onCreate() {
585	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
586	    }
587	
588	    /**
589	     * Resolves the effective registration date and rolls it onto a business day. An absent
590	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
591	     * The resulting date is then rolled forward so it never falls on a weekend: a Saturday or Sunday
592	     * becomes the following Monday, while any weekday is returned unchanged.
593	     *
594	     * <p>This is the single definition of both the defaulting and the business-day roll, used
595	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
596	     * stamps the owner and by the create endpoint that counts owners per business day.
597	     *
598	     * @param supplied the registration date from the request, or {@code null} when none was supplied
599	     * @return the effective registration date, guaranteed to fall on a business day
600	     */
601	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
602	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
603	        return switch (effective.getDayOfWeek()) {
604	            case SATURDAY -> effective.plusDays(2);
605	            case SUNDAY -> effective.plusDays(1);
606	            default -> effective;
607	        };
608	    }
