644	    }
645	
646	    /**
647	     * Return the Pet with the given name, or null if none found for this Owner.
648	     *
649	     * @param name to test
650	     * @return true if pet name is already in use
651	     */
652	    public Pet getPet(String name, boolean ignoreNew) {
653	        name = name.toLowerCase();
654	        for (Pet pet : getPetsInternal()) {
655	            if (!ignoreNew || !pet.isNew()) {
656	                String compName = pet.getName();
657	                compName = compName.toLowerCase();
658	                if (compName.equals(name)) {
659	                    return pet;
660	                }
661	            }
662	        }
663	        return null;
664	    }
665	
666	    public Pet getPet(Integer petId) {
667	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
668	    }
669	
670	    @Override
671	    public String toString() {
672	        return new ToStringCreator(this)
673	
674	            .append("id", this.getId())
675	            .append("new", this.isNew())
676	            .append("lastName", this.getLastName())
677	            .append("firstName", this.getFirstName())
678	            .append("address", this.address)
679	            .append("city", this.city)
680	            .append("telephone", this.telephone)
681	            .toString();
682	    }
683	}
